from html.parser import HTMLParser
from rich.console import Console

class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ('meta',):
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if not self.stack or self.stack[-1] != tag:
            self.errors.append(f'mismatch: expected </{self.stack[-1] if self.stack else None}> got </{tag}>')
        else:
            self.stack.pop()

p = P()
